TOT=$(find AlgebraicJacobian -name '*.lean' | wc -l) && echo "total .lean under AlgebraicJacobian = $TOT"
python3 - <<'EOF'
import re,os
root='AlgebraicJacobian.lean'
def imports(p):
    out=[]
    try:
        for L in open(p,encoding='utf-8'):
            m=re.match(r'^import\s+(AlgebraicJacobian[\w.]*)',L)
            if m: out.append(m.group(1))
            elif L.strip() and not L.startswith('import') and not L.startswith('/-') and not L.startswith('--'):
                pass
    except Exception: pass
    return out
def path(mod): return mod.replace('.','/')+'.lean'
seen=set(); stack=imports(root)
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    p=path(m)
    if os.path.exists(p): stack.extend(imports(p))
allf={f[:-5].replace('/','.') for f in
      (os.path.join(dp,fn) for dp,_,fns in os.walk('AlgebraicJacobian') for fn in fns if fn.endswith('.lean'))}
unre=sorted(allf-seen)
print("reachable =",len(seen),"  unreachable =",len(unre))
for u in unre: print("   ",u)
EOF
